"""
CSV Cleaner Tool

This module provides functionality to clean CSV data files by:
- Inferring column data types
- Applying missing value imputation strategies
- Deduplicating rows
- Flagging outliers using z-score method
- Generating a detailed cleaning report

Configuration driven via config.json for column rules and thresholds
"""

import csv
import json
import math
import statistics
from collections import defaultdict, Counter
from typing import List, Dict, Any, Union, Optional

class CSVCleaner:
    """A class to clean CSV data files with multiple cleaning features."""

    def __init__(self, config_path: str):
        """Initialize the cleaner with configuration file path."""
        with open(config_path, 'r') as f:
            self.config = json.load(f)
        self.column_types = {}
        self.missing_value_strategies = {}
        self.outlier_thresholds = {}
        self.columns = []
        self.report = {
            'total_rows': 0,
            'detected_duplicates': 0,
            'missing_value_filled': {},
            'outliers_flagged': {},
            'type_inference': {},
        }

    def infer_column_types(self, data: List[Dict[str, str]]) -> None:
        """Infer data type per column using simple heuristics."""
        type_counts = {col: Counter() for col in data[0].keys()} if data else {}
        for row in data:
            for col, val in row.items():
                if val == '' or val is None:
                    continue
                if self.is_int(val):
                    type_counts[col]['int'] += 1
                elif self.is_float(val):
                    type_counts[col]['float'] += 1
                else:
                    type_counts[col]['str'] += 1
        for col, counts in type_counts.items():
            # Choose the most common type, favoring int > float > str
            if counts['str'] > 0:
                inferred = 'str'
            elif counts['float'] > 0:
                inferred = 'float'
            elif counts['int'] > 0:
                inferred = 'int'
            else:
                inferred = 'str'
            self.column_types[col] = inferred
            self.report['type_inference'][col] = inferred

    def is_int(self, s: str) -> bool:
        try:
            int(s)
            return True
        except ValueError:
            return False

    def is_float(self, s: str) -> bool:
        try:
            float(s)
            return True
        except ValueError:
            return False

    def apply_missing_value_strategy(self, data: List[Dict[str, str]]) -> None:
        """Fill missing values based on configured strategies per column."""
        # Prepare replacement values
        replacements = {}
        for col in self.columns:
            strategy = self.config['missing_value_strategies'].get(col, 'none')
            self.missing_value_strategies[col] = strategy
            values = [row[col] for row in data if row[col] != '']
            dtype = self.column_types.get(col, 'str')
            replacement = None
            if strategy == 'mean' and dtype in ('int', 'float') and values:
                nums = list(map(float, values))
                replacement = str(statistics.mean(nums))
            elif strategy == 'median' and dtype in ('int', 'float') and values:
                nums = list(map(float, values))
                replacement = str(statistics.median(nums))
            elif strategy == 'mode' and values:
                replacement = Counter(values).most_common(1)[0][0]
            elif strategy == 'constant':
                replacement = self.config['missing_value_constants'].get(col, '')
            elif strategy == 'none':
                replacement = ''
            replacements[col] = replacement

        filled_counts = defaultdict(int)
        for row in data:
            for col in self.columns:
                if row[col] == '':
                    row[col] = replacements[col] if replacements[col] is not None else ''
                    if replacements[col] not in ('', None):
                        filled_counts[col] += 1
        self.report['missing_value_filled'] = dict(filled_counts)

    def deduplicate_rows(self, data: List[Dict[str, str]]) -> List[Dict[str, str]]:
        """Remove duplicate rows from the data."""
        seen = set()
        unique_data = []
        for row in data:
            key = tuple(row[col] for col in self.columns)
            if key in seen:
                self.report['detected_duplicates'] += 1
                continue
            seen.add(key)
            unique_data.append(row)
        return unique_data

    def flag_outliers(self, data: List[Dict[str, str]]) -> None:
        """Flag outliers in numeric columns using z-score and a threshold."""
        # Gather numeric values column-wise
        numeric_cols = [col for col, typ in self.column_types.items() if typ in ('int', 'float')]
        values = {col: [] for col in numeric_cols}
        for row in data:
            for col in numeric_cols:
                try:
                    val = float(row[col])
                    values[col].append(val)
                except ValueError:
                    # Ignore non-convertible values
                    pass

        # Calculate mean and std dev
        stats = {}
        for col in numeric_cols:
            col_vals = values[col]
            if len(col_vals) < 2:
                stats[col] = (None, None)
            else:
                mean_val = statistics.mean(col_vals)
                std_val = statistics.stdev(col_vals)
                stats[col] = (mean_val, std_val)

        threshold = self.config.get('outlier_z_threshold', 3.0)
        self.outlier_thresholds = {col: threshold for col in numeric_cols}
        # Add flags in data
        for row in data:
            for col in numeric_cols:
                mean_val, std_val = stats.get(col, (None, None))
                if mean_val is None or std_val is None or std_val == 0:
                    flag = False
                else:
                    try:
                        val = float(row[col])
                        z_score = abs((val - mean_val) / std_val)
                        flag = (z_score > threshold)
                    except ValueError:
                        flag = False
                flag_col = f'{col}_outlier'
                row[flag_col] = 'True' if flag else 'False'
                if flag:
                    self.report['outliers_flagged'][col] = self.report['outliers_flagged'].get(col, 0) + 1

    def load_csv(self, path: str) -> List[Dict[str, str]]:
        """Load CSV file and return list of dict rows."""
        with open(path, 'r', newline='') as f:
            reader = csv.DictReader(f)
            self.columns = reader.fieldnames
            return [row for row in reader]

    def save_csv(self, data: List[Dict[str, str]], path: str) -> None:
        """Save list of dict rows to CSV file."""
        if not data:
            return
        with open(path, 'w', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=data[0].keys())
            writer.writeheader()
            writer.writerows(data)

    def generate_report(self) -> str:
        """Generate a human-readable cleaning report."""
        lines = ["CSV Cleaning Report"]
        lines.append(f"Total rows processed: {self.report['total_rows']}")
        lines.append(f"Duplicates removed: {self.report['detected_duplicates']}")
        lines.append("Missing values filled per column:")
        for col, count in self.report['missing_value_filled'].items():
            lines.append(f"  {col}: {count}")
        lines.append("Outliers flagged per numeric column:")
        for col, count in self.report['outliers_flagged'].items():
            lines.append(f"  {col}: {count}")
        lines.append("Inferred column types:")
        for col, typ in self.report['type_inference'].items():
            lines.append(f"  {col}: {typ}")
        return '\n'.join(lines)

    def clean(self, input_path: str, output_path: str) -> None:
        """Full cleaning pipeline: load, infer types, handle missing, dedupe, flag outliers, save."""
        data = self.load_csv(input_path)
        self.report['total_rows'] = len(data)
        if not data:
            print("No data to clean.")
            return
        self.infer_column_types(data)
        self.apply_missing_value_strategy(data)
        data = self.deduplicate_rows(data)
        self.flag_outliers(data)
        self.save_csv(data, output_path)


def generate_messy_data(path: str) -> None:
    """Generate an example messy CSV dataset with missing values, outliers, duplicates."""
    import random
    import datetime

    headers = ["id", "age", "height", "weight", "gender", "score"]
    genders = ["male", "female", "other", ""]  # Empty gender as missing

    random.seed(42)
    data = []
    for i in range(100):
        # Introduce missing randomly
        age = random.choice([str(random.randint(18, 65)), ''])
        height = random.choice([str(round(random.uniform(150, 200), 1)), ''])
        weight = random.choice([str(round(random.uniform(50, 100), 1)), ''])
        gender = random.choice(genders)
        score = random.choice([str(round(random.uniform(0, 100), 2)), ''])

        data.append({
            "id": str(i),
            "age": age,
            "height": height,
            "weight": weight,
            "gender": gender,
            "score": score
        })

    # Add duplicates
    data.extend(data[10:15])

    # Add outliers
    data.append({"id": "outlier1", "age": "120", "height": "250", "weight": "300", "gender": "male", "score": "5"})
    data.append({"id": "outlier2", "age": "15",  "height": "100", "weight": "30",  "gender": "female", "score": "95"})

    with open(path, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=headers)
        writer.writeheader()
        writer.writerows(data)


def main():
    import os
    input_csv = "/work/messy.csv"
    output_csv = "/work/cleaned.csv"
    config_path = "/work/config.json"

    # Generate messy data file
    generate_messy_data(input_csv)

    # Create cleaner instance
    cleaner = CSVCleaner(config_path)

    # Clean the data
    cleaner.clean(input_csv, output_csv)

    # Print report
    print(cleaner.generate_report())

if __name__ == '__main__':
    main()
